const pending = new Set();
const setting = (key, fallback) => MODS.getSetting(key, fallback);
const resetRuntime = () => pending.clear();
MODS.registerNarrationOrchestrator({ id: 'diagnostic-exchange', priority: -100, isActive: async () => setting('enabled', false) });
MODS.registerHook('onSceneBeat', envelope => { if (envelope?.exchangeId) pending.add(envelope.exchangeId); });
MODS.registerHook('onSceneExchangeClosed', async envelope => {
  const targetId = envelope?.exchangeId;
  if (!targetId || !pending.delete(targetId)) return;
  const owns = await MODS.ownsNarrationExchange(envelope);
  const context = MODS.getNarrationContext({ exchangeId: targetId, recentBeatLimit: 3, activityLimit: 2 });
  if (await setting('writeActivityLog', true)) MODS.log(`Narration exchange ${targetId}: owner=${owns}; mode=${context.mode}; beats=${context.recentBeats.length}; characters=${context.characters.length}`);
  if (!owns) return;
  MODS.publishNarration({ id: `yaw_narration_diagnostics_first_party.exchange.${targetId}`, scope: 'exchange', targetId, status: 'ready', text: `Diagnostic context: mode ${context.mode}; ${context.recentBeats.length} bounded beats; ${context.characters.length} public characters.`, profileId: 'diagnostic', providerId: 'local-diagnostics', outputRating: envelope.policy?.posture === 'mature' ? 'mature' : 'safe' });
});
MODS.registerHook('onContentPolicyChanged', resetRuntime);
MODS.registerHook('onGameStart', resetRuntime);
MODS.registerHook('onGameLoad', resetRuntime);
